insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token) select '00000000-0000-0000-0000-000000000000',id,'authenticated','authenticated',email,extensions.crypt('LocalDemo-Only-2026!',extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}'::jsonb,jsonb_build_object('full_name',name),now(),now(),'','','','' from (values('10000000-0000-0000-0000-000000000001'::uuid,'alex@example.test','Alex Kumar'),('10000000-0000-0000-0000-000000000002'::uuid,'maya@example.test','Maya Joseph'),('10000000-0000-0000-0000-000000000003'::uuid,'rahul@example.test','Rahul Nair'),('10000000-0000-0000-0000-000000000004'::uuid,'tina@example.test','Tina George'),('10000000-0000-0000-0000-000000000005'::uuid,'viewer@example.test','Demo Viewer'),('10000000-0000-0000-0000-000000000006'::uuid,'outside@example.test','Other Project Member')) v(id,email,name);
insert into auth.identities(id,user_id,provider_id,identity_data,provider,created_at,updated_at) select gen_random_uuid(),id,id::text,jsonb_build_object('sub',id::text,'email',email,'email_verified',true),'email',now(),now() from auth.users where email like '%@example.test';
insert into public.projects(id,name,code,currency,created_by,start_date) values('20000000-0000-0000-0000-000000000001','Project Aurora','AURORA-01','INR','10000000-0000-0000-0000-000000000001','2026-09-01'),('20000000-0000-0000-0000-000000000002','Weather Node','WXNODE','INR','10000000-0000-0000-0000-000000000006','2026-09-01');
insert into public.project_members(project_id,user_id,role) select '20000000-0000-0000-0000-000000000001',id,case email when 'alex@example.test' then 'OWNER'::public.project_role when 'maya@example.test' then 'FINANCE_MANAGER' when 'tina@example.test' then 'APPROVER' when 'viewer@example.test' then 'VIEWER' else 'MEMBER' end from auth.users where email like '%@example.test' and email<>'outside@example.test';
insert into public.project_members(project_id,user_id,role) values('20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000006','OWNER');
insert into public.categories(project_id,name) select '20000000-0000-0000-0000-000000000001',unnest(array['Electronics','Mechanical','Travel','Registration','Reserve','Other']);
insert into public.categories(project_id,name) select '20000000-0000-0000-0000-000000000002',unnest(array['Electronics','Other']);
do $$ declare p uuid:='20000000-0000-0000-0000-000000000001'; bank uuid; cat uuid; mech uuid; vendor uuid; grant_id uuid; pur uuid; claim uuid; bill uuid; req uuid; adv uuid; budget uuid; allocation uuid; outside uuid:='10000000-0000-0000-0000-000000000006'; r jsonb; begin
perform set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
bank:=private.account(p,'BANK'); perform private.account(p,'EXPENSE'); perform private.account(p,'FUNDING'); perform private.account(p,'VENDOR_PAYABLE');
select id into cat from public.categories where project_id=p and name='Electronics'; select id into mech from public.categories where project_id=p and name='Mechanical';
foreach r in array array['{"name":"Institute Grant","amount":"10000000","type":"grant"}'::jsonb,'{"name":"Team Contribution","amount":"2500000","type":"member_contribution"}'::jsonb,'{"name":"Sponsor","amount":"2500000","type":"sponsor"}'::jsonb] loop grant_id:=public.save_record(p,'funding_sources',jsonb_build_object('name',r->>'name','type',r->>'type','sanctioned_amount_minor',r->>'amount')); perform public.post_financial(p,jsonb_build_object('type','FUNDING','idempotency_key',gen_random_uuid(),'source_id',grant_id,'account_id',bank,'amount_minor',r->>'amount','description',r->>'name','date','2026-09-01')); end loop;
vendor:=public.save_record(p,'vendors','{"name":"ElectroHub","gstin":"DEMO ONLY"}'); perform public.save_record(p,'vendors','{"name":"MakerSupply"}'); perform public.save_record(p,'vendors','{"name":"CloudHost"}');
pur:=public.save_purchase(p,jsonb_build_object('vendor_id',vendor,'category_id',cat,'date','2026-09-05','invoice_number','EH-001','notes','Flight controller','items',jsonb_build_array(jsonb_build_object('description','Flight Controller','quantity','1','unit_price_minor','3245000','mark_as_asset',true)),'allocations',jsonb_build_array(jsonb_build_object('source_type','PROJECT_ACCOUNT','project_account_id',bank,'amount_minor','3245000')))); perform public.post_financial(p,jsonb_build_object('type','PURCHASE','source_id',pur,'idempotency_key',gen_random_uuid(),'date','2026-09-05'));
perform public.post_financial(p,jsonb_build_object('type','REFUND','source_id',pur,'idempotency_key',gen_random_uuid(),'amount_minor','60000','date','2026-09-20','allocations',jsonb_build_array(jsonb_build_object('destination','PROJECT_ACCOUNT','account_id',bank,'amount_minor','60000'))));
pur:=public.save_purchase(p,jsonb_build_object('vendor_id',vendor,'category_id',cat,'date','2026-09-07','invoice_number','EH-002','notes','Rahul pays for motors','items',jsonb_build_array(jsonb_build_object('description','Motors','quantity','1','unit_price_minor','620000')),'allocations',jsonb_build_array(jsonb_build_object('source_type','MEMBER','member_user_id','10000000-0000-0000-0000-000000000003','amount_minor','620000')))); perform public.post_financial(p,jsonb_build_object('type','PURCHASE','source_id',pur,'idempotency_key',gen_random_uuid(),'date','2026-09-07'));
select id into allocation from public.purchase_funding_allocations where purchase_id=pur;
claim:=public.save_record(p,'reimbursement_claims',jsonb_build_object('member_user_id','10000000-0000-0000-0000-000000000003','notes','Motor purchase reimbursement','items',jsonb_build_array(jsonb_build_object('allocation_id',allocation,'amount_minor','620000')))); perform public.submit_approval(p,'reimbursement_claims',claim); perform public.post_financial(p,jsonb_build_object('type','REIMBURSEMENT','source_id',claim,'idempotency_key',gen_random_uuid(),'account_id',bank,'amount_minor','400000','date','2026-09-09'));
vendor:=public.save_record(p,'vendors','{"name":"ProtoFab"}'); bill:=public.save_record(p,'bills',jsonb_build_object('vendor_id',vendor,'category_id',mech,'invoice_number','PF-001','total_minor','1240000','due_date','2026-10-15','date','2026-09-10','notes','Prototype fabrication')); perform public.post_financial(p,jsonb_build_object('type','BILL','source_id',bill,'idempotency_key',gen_random_uuid(),'date','2026-09-10'));
req:=public.save_record(p,'purchase_requests','{"title":"Batteries","estimated_minor":"900000","reason":"Competition power pack"}'); perform public.submit_approval(p,'purchase_requests',req);
pur:=public.save_purchase(p,jsonb_build_object('category_id',cat,'linked_request_id',req,'date','2026-09-12','notes','Battery purchase','items',jsonb_build_array(jsonb_build_object('description','Batteries','quantity','1','unit_price_minor','860000')),'allocations',jsonb_build_array(jsonb_build_object('source_type','PROJECT_ACCOUNT','project_account_id',bank,'amount_minor','860000')))); perform public.post_financial(p,jsonb_build_object('type','PURCHASE','source_id',pur,'idempotency_key',gen_random_uuid(),'date','2026-09-12')); update public.purchase_requests set status='completed' where id=req;
adv:=public.save_record(p,'advances','{"member_user_id":"10000000-0000-0000-0000-000000000002","purpose":"Workshop materials"}'); perform public.post_financial(p,jsonb_build_object('type','ADVANCE','source_id',adv,'idempotency_key',gen_random_uuid(),'account_id',bank,'amount_minor','1000000','date','2026-09-13'));
pur:=public.save_purchase(p,jsonb_build_object('category_id',mech,'date','2026-09-15','notes','Workshop materials from advance','items',jsonb_build_array(jsonb_build_object('description','Workshop materials','quantity','1','unit_price_minor','715000')),'allocations',jsonb_build_array(jsonb_build_object('source_type','ADVANCE','advance_id',adv,'amount_minor','715000')))); perform public.post_financial(p,jsonb_build_object('type','PURCHASE','source_id',pur,'idempotency_key',gen_random_uuid(),'date','2026-09-15')); perform public.post_financial(p,jsonb_build_object('type','ADVANCE_RETURN','source_id',adv,'idempotency_key',gen_random_uuid(),'account_id',bank,'amount_minor','285000','date','2026-09-18')); update public.advances set status='closed' where id=adv;
insert into public.budgets(project_id,name,start_date,end_date) values(p,'Project budget','2026-09-01','2027-08-31') returning id into budget;
insert into public.budget_lines(project_id,budget_id,category_id,planned_minor) select p,budget,id,case name when 'Electronics' then 6000000 when 'Mechanical' then 4000000 when 'Travel' then 2000000 when 'Registration' then 1000000 else 2000000 end from public.categories where project_id=p and name<>'Other';
insert into public.assets(project_id,name,asset_tag,currency,purchase_value_minor,notes) values(p,'Camera Module','CAM-OPENING','INR',0,'Opening donated asset; no cash purchase invented.');
perform set_config('request.jwt.claim.sub',outside::text,true); bank:=private.account('20000000-0000-0000-0000-000000000002','BANK'); grant_id:=public.save_record('20000000-0000-0000-0000-000000000002','funding_sources','{"name":"Opening Funding","type":"grant"}'); perform public.post_financial('20000000-0000-0000-0000-000000000002',jsonb_build_object('type','FUNDING','source_id',grant_id,'idempotency_key',gen_random_uuid(),'account_id',bank,'amount_minor','5000000','date','2026-09-01'));
end $$;
